/* Operación diaria: coordenadas, geometrías y actualización de cobertura. */
(function(root){'use strict';
function coordinate(value){const s=String(value??'').trim().replace(/^\(\s*|\s*\)$/g,'');const m=s.match(/^([+-]?\d+(?:\.\d+)?)\s*(?:,|;|\s)\s*([+-]?\d+(?:\.\d+)?)$/);if(!m)return null;const p=[Number(m[1]),Number(m[2])];return p.every(Number.isFinite)&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180?p:null}
function ringKey(ring){const points=ring.map(p=>p[0]+','+p[1]);if(points.length>1&&points[0]===points.at(-1))points.pop();if(!points.length)return '';let best=null;for(const seq of [points,[...points].reverse()]){const smallest=[...seq].sort()[0];for(let i=0;i<seq.length;i++){if(seq[i]!==smallest)continue;const k=seq.slice(i).concat(seq.slice(0,i)).join(';');if(best===null||k<best)best=k}}return best}
function shapeKey(p){return JSON.stringify([p.name,ringKey(p.rings[0]),p.rings.slice(1).map(ringKey).sort()])}
function unique(polygons){const seen=new Set();return polygons.filter(p=>{const key=shapeKey(p);if(seen.has(key))return false;seen.add(key);return true})}
function merge(oldPolygons,incoming){const fresh=unique(incoming),names=new Set(fresh.map(p=>p.name)),old=unique(oldPolygons||[]),oldKeys=new Set(old.map(shapeKey));const added=fresh.filter(p=>!old.some(o=>o.name===p.name)).length,repeated=fresh.filter(p=>oldKeys.has(shapeKey(p))).length,updated=fresh.length-added-repeated;return {polygons:unique([...old.filter(p=>!names.has(p.name)),...fresh]),added,repeated,updated,duplicates:incoming.length-fresh.length}}
function onSegment(p,a,b){const cross=(p[1]-a[1])*(b[0]-a[0])-(p[0]-a[0])*(b[1]-a[1]);return Math.abs(cross)<1e-10&&p[0]>=Math.min(a[0],b[0])-1e-10&&p[0]<=Math.max(a[0],b[0])+1e-10&&p[1]>=Math.min(a[1],b[1])-1e-10&&p[1]<=Math.max(a[1],b[1])+1e-10}
function inRing(p,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[j],b=ring[i];if(a[0]===b[0]&&a[1]===b[1])continue;if(onSegment(p,a,b))return true;if((b[0]>p[0])!==(a[0]>p[0])&&p[1]<(a[1]-b[1])*(p[0]-b[0])/(a[0]-b[0])+b[1])inside=!inside}return inside}
function contains(p,polygon){return polygon.rings.length&&inRing(p,polygon.rings[0])&&!polygon.rings.slice(1).some(r=>inRing(p,r))}
function namesAt(p,polygons){return [...new Set(polygons.filter(x=>contains(p,x)).map(x=>x.name))]}
function extractKML(xml){const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.getElementsByTagName('parsererror').length||doc.getElementsByTagNameNS('*','parsererror').length)throw Error('El archivo KML contiene errores de XML.');const all=(el,name)=>Array.from(el.getElementsByTagNameNS('*',name));if(doc.documentElement.localName!=='kml')throw Error('El archivo no es un documento KML.');const polygons=[];let invalid=0;for(const pm of all(doc,'Placemark')){const direct=Array.from(pm.children).find(x=>x.localName==='name');const name=direct?.textContent.trim();for(const pg of all(pm,'Polygon')){if(!name){invalid++;continue}const boundary=all(pg,'outerBoundaryIs')[0];const outers=boundary&&all(boundary,'coordinates')[0];const inners=all(pg,'innerBoundaryIs').map(x=>all(x,'coordinates')[0]);const elements=[outers,...inners];const rings=elements.map(el=>{if(!el)return null;const tokens=el.textContent.trim().split(/\s+/);const ring=tokens.map(t=>{const nums=t.split(',');return nums.length>=2&&nums[0].trim()&&nums[1].trim()?[Number(nums[1]),Number(nums[0])]:[NaN,NaN]});if(ring.some(p=>!p.every(Number.isFinite)||Math.abs(p[0])>90||Math.abs(p[1])>180)||new Set(ring.map(p=>p.join(','))).size<3)return null;if(ring[0].join(',')!==ring.at(-1).join(','))ring.push([...ring[0]]);return ring});if(rings.some(r=>!r)){invalid++;continue}polygons.push({name,rings})}}return {polygons,invalid}}
const api={coordinate,ringKey,shapeKey,unique,merge,contains,namesAt,extractKML};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.odGeo=api;
})(typeof window==='undefined'?globalThis:window);
